-- Migration: 20261104050000_phase11_tag_management.sql
-- Description: Phase 11 tag management restricted to tenant owners and managers.
--              Tags in another tenant are reported as not-found. Tag IDs stay globally unique
--              and are generated by the app (generateRandomTagId) with the verifyTap format.

-- -----------------------------------------------------------------------------
-- 1. CREATE TAG
-- -----------------------------------------------------------------------------

create or replace function public.create_tag(
  p_actor uuid,
  p_tenant uuid,
  p_tag_id text,
  p_label text default null
) returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tag text;
  v_inserted integer;
begin
  if coalesce(private.member_role(p_actor, p_tenant), '') not in ('owner', 'manager') then
    return 'unauthorized';
  end if;

  v_tag := pg_catalog.btrim(p_tag_id);
  if v_tag is null or v_tag !~ '^[A-Za-z0-9_-]{8,128}$' then
    return 'invalid-tag-id';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_tag, 1002));

  insert into public.tags (id, label, active, tenant_id)
  values (v_tag, nullif(pg_catalog.btrim(p_label), ''), true, p_tenant)
  on conflict (id) do nothing;
  get diagnostics v_inserted = row_count;

  if v_inserted = 0 then
    return 'duplicate';
  end if;

  insert into public.audit_log (tenant_id, actor, action, target)
  values (p_tenant, p_actor, 'create_tag', v_tag);

  return 'created';
end;
$$;

revoke all on function public.create_tag(uuid, uuid, text, text) from public, anon, authenticated;
grant execute on function public.create_tag(uuid, uuid, text, text) to service_role;

-- -----------------------------------------------------------------------------
-- 2. DEACTIVATE TAG
-- -----------------------------------------------------------------------------

create or replace function public.deactivate_tag(
  p_actor uuid,
  p_tenant uuid,
  p_tag_id text
) returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tag text;
  v_updated integer;
begin
  if coalesce(private.member_role(p_actor, p_tenant), '') not in ('owner', 'manager') then
    return 'unauthorized';
  end if;

  v_tag := pg_catalog.btrim(p_tag_id);
  if v_tag is null or v_tag = '' then
    return 'not-found';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_tag, 1002));

  update public.tags
  set active = false,
      deactivated_at = pg_catalog.now()
  where id = v_tag
    and tenant_id = p_tenant
    and active = true;
  get diagnostics v_updated = row_count;

  if v_updated = 0 then
    return 'not-found';
  end if;

  insert into public.audit_log (tenant_id, actor, action, target)
  values (p_tenant, p_actor, 'deactivate_tag', v_tag);

  return 'deactivated';
end;
$$;

revoke all on function public.deactivate_tag(uuid, uuid, text) from public, anon, authenticated;
grant execute on function public.deactivate_tag(uuid, uuid, text) to service_role;

-- -----------------------------------------------------------------------------
-- 3. ROTATE TAG (create the replacement, then retire the old tag, atomically)
-- -----------------------------------------------------------------------------

create or replace function public.rotate_tag(
  p_actor uuid,
  p_tenant uuid,
  p_old_tag_id text,
  p_new_tag_id text,
  p_label text default null
) returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_old text;
  v_new text;
  v_label text;
  v_inserted integer;
begin
  if coalesce(private.member_role(p_actor, p_tenant), '') not in ('owner', 'manager') then
    return 'unauthorized';
  end if;

  v_old := pg_catalog.btrim(p_old_tag_id);
  v_new := pg_catalog.btrim(p_new_tag_id);

  if v_new is null or v_new !~ '^[A-Za-z0-9_-]{8,128}$' then
    return 'invalid-tag-id';
  end if;

  if v_old is null or v_old = '' then
    return 'not-found';
  end if;

  -- Two tag locks in canonical order (deadlock-free, as in merge's customer locks)
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(least(v_old, v_new), 1002));
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(greatest(v_old, v_new), 1002));

  select t.label into v_label
  from public.tags as t
  where t.id = v_old
    and t.tenant_id = p_tenant
    and t.active = true;

  if not found then
    return 'not-found';
  end if;

  insert into public.tags (id, label, active, tenant_id)
  values (v_new, coalesce(nullif(pg_catalog.btrim(p_label), ''), v_label), true, p_tenant)
  on conflict (id) do nothing;
  get diagnostics v_inserted = row_count;

  if v_inserted = 0 then
    return 'duplicate';
  end if;

  update public.tags
  set active = false,
      deactivated_at = pg_catalog.now()
  where id = v_old;

  insert into public.audit_log (tenant_id, actor, action, target, detail)
  values (
    p_tenant,
    p_actor,
    'rotate_tag',
    v_old,
    pg_catalog.jsonb_build_object('new_tag_id', v_new)
  );

  return 'rotated';
end;
$$;

revoke all on function public.rotate_tag(uuid, uuid, text, text, text) from public, anon, authenticated;
grant execute on function public.rotate_tag(uuid, uuid, text, text, text) to service_role;
